describe('Error Page Handling', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/data', {
            statusCode: 500,
            body: { error: 'Internal Server Error' },
        }).as('getData');
        cy.visit('/'); // Adjust the URL to your application's entry point
    });

    it('should display the error page on 500 server error', () => {
        cy.wait('@getData');
        cy.get('.error-page').should('be.visible');
        cy.get('.error-page').contains('Internal Server Error');
    });

    it('should not display the error page on successful response', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 200,
            body: { data: 'Success' },
        }).as('getDataSuccess');

        cy.reload();
        cy.wait('@getDataSuccess');
        cy.get('.error-page').should('not.exist');
        cy.get('.success-message').should('be.visible').contains('Success');
    });
});
